<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { NAlert, NButton, NCollapse, NCollapseItem, NInput, NSelect, NSwitch, NTag, NTabs, NTabPane } from 'naive-ui';
import { Bell, ExternalLink, FolderOpen, Gauge, Info, RefreshCw, ShieldCheck } from 'lucide-vue-next';
import { invoke } from '../../bridge.ts';
import type { ControlStore } from '../control-types.ts';
const props = defineProps<{ store: ControlStore }>();
const tab = ref('general');
const busy = ref('');
const websiteUrl = ref(props.store.settings.websiteUrl);
const automatic = ref(props.store.settings.automaticUpdates);
const updateUrl = ref(props.store.settings.updateUrl);
const sourceDirty = ref(false);
watch(() => props.store.settings.websiteUrl, value => { if (!sourceDirty.value) websiteUrl.value = value; });
watch(() => props.store.settings.automaticUpdates, value => { if (!sourceDirty.value) automatic.value = value; });
watch(() => props.store.settings.updateUrl, value => { updateUrl.value = value; });
const announcements = computed(() => props.store.website.announcements);
const lastUpdate = computed(() => props.store.website.update);
async function act(key: string, action: () => Promise<unknown>, success?: string) { busy.value = key; try { await action(); if (success) props.store.notify(success); } catch (error) { props.store.notify(error, 'error'); } finally { busy.value = ''; } }
async function saveSource() { await props.store.configureWebsite(websiteUrl.value, automatic.value); sourceDirty.value = false; }
async function saveUpdateSource() { if (!props.store.desktop) throw new Error('请在桌面应用中设置更新服务'); await invoke('set_update_source', { url: updateUrl.value }); await props.store.refreshSettings(); }
</script>
<template>
  <section class="ui-page settings-page" data-testid="settings-page">
    <header class="page-header"><div><div class="page-eyebrow">PREFERENCES</div><h1>设置与关于</h1><p class="page-subtitle">管理运行偏好、内容来源与应用信息。</p></div></header>
    <NTabs v-model:value="tab" type="line" animated class="settings-tabs"><NTabPane name="general"><template #tab>通用设置</template><div class="settings-content">
      <section class="surface"><div class="section-heading"><div><h2>运行偏好</h2><p>启动与动画</p></div><Gauge :size="20" /></div><div class="setting-row"><div><b>开机自动启动</b><p>{{ store.startup.available ? '登录电脑后恢复上次的桌面，不自动弹出设置。' : '请在正式桌面应用中设置。' }}</p></div><NSwitch :value="store.settings.autostart" :disabled="!store.startup.available || !!busy" :loading="busy === 'startup'" @update:value="value => act('startup', () => store.setAutostart(value))" /></div><NAlert v-if="store.startup.error" type="warning" :show-icon="false">{{ store.startup.error }}</NAlert><div class="setting-row"><div><b>暂停桌面动画</b><p>暂停小伴与动态壁纸，不影响提醒的计时。</p></div><NSwitch :value="store.settings.paused" :disabled="!!busy" :loading="busy === 'pause'" @update:value="value => act('pause', () => store.updateAppearance({ paused: value }))" /></div><div class="setting-row"><div><b>动画帧率</b><p>30 帧更省资源，60 帧更流畅。</p></div><NSelect style="width:145px" :value="store.settings.fps" :options="[{ label: '30 帧 · 节能', value: 30 }, { label: '60 帧 · 流畅', value: 60 }]" :disabled="!!busy" @update:value="value => act('fps', () => store.updateAppearance({ fps: value }))" /></div></section>
      <section class="surface"><div class="section-heading"><div><h2>壁纸网站</h2><p>在线内容、版本与公告的来源</p></div><ExternalLink :size="20" /></div><div class="source-field"><label>网站地址</label><NInput v-model:value="websiteUrl" placeholder="https://wallpaper.xiangban.xyz" @update:value="sourceDirty = true" /></div><div class="setting-row"><div><b>自动检查版本与公告</b><p>启动时检查，之后每 30 分钟同步一次。</p></div><NSwitch v-model:value="automatic" @update:value="sourceDirty = true" /></div><div class="settings-actions"><NButton type="primary" :disabled="!store.desktop || !!busy" :loading="busy === 'source'" @click="act('source', saveSource, '壁纸来源已保存')">保存来源设置</NButton><NButton :disabled="!store.desktop || !!busy" :loading="busy === 'check'" @click="act('check', () => store.checkWebsite(), '已完成版本与公告检查')"><template #icon><RefreshCw :size="15" /></template>立即同步</NButton><span v-if="sourceDirty" class="unsaved-note">有未保存的修改</span></div><NAlert v-if="store.website.errors.length" type="warning" :show-icon="false" class="source-errors">{{ store.website.errors.join('；') }}</NAlert><NCollapse class="advanced-source"><NCollapseItem title="高级：独立更新服务" name="updates"><p class="muted">仅在使用独立更新地址时调整。</p><div class="inline-field"><NInput v-model:value="updateUrl" placeholder="https://…/updates.json" /><NButton :disabled="!store.desktop || !!busy" @click="act('update-source', saveUpdateSource, '更新地址已保存')">保存</NButton></div></NCollapseItem></NCollapse></section>
      <section class="surface"><div class="section-heading"><div><h2>本地数据</h2><p>壁纸、游戏存档与提醒都保存在本机</p></div><FolderOpen :size="20" /></div><div class="data-location"><code>{{ store.info.dataDirectory || '桌面应用中可查看实际保存位置' }}</code><NButton :disabled="!store.desktop" @click="act('directory', () => invoke('open_data_directory'))"><template #icon><FolderOpen :size="15" /></template>打开目录</NButton></div></section>
    </div></NTabPane><NTabPane name="about"><template #tab>关于与更新</template><div class="settings-content">
      <section class="surface about-identity"><div class="about-logo"><img src="/xiaoban.svg" alt="小伴"></div><div><h2>小伴桌面</h2><p>一点陪伴，让桌面更有意思。</p><NTag :bordered="false" size="small">v{{ store.info.version }}</NTag><NTag :bordered="false" size="small">{{ store.info.platform === 'windows' ? 'Windows · 64 位' : store.info.platform === 'macos' ? 'macOS' : '浏览器预览' }}</NTag></div></section>
      <section class="surface"><div class="section-heading"><div><h2>应用更新</h2><p>{{ lastUpdate?.available ? `发现新版本 v${lastUpdate.version}` : lastUpdate ? '已完成检查，当前没有更新' : '检查新版本与发布说明' }}</p></div><NButton :loading="busy === 'check'" :disabled="!store.desktop || !!busy" @click="act('check', () => store.checkWebsite())"><template #icon><RefreshCw :size="15" /></template>检查更新</NButton></div><div v-if="lastUpdate?.available" class="release-details"><small class="muted">{{ lastUpdate.publishedAt }}</small><p>{{ lastUpdate.notes }}</p><NButton type="primary" @click="act('download', () => invoke('open_download_url', { url: lastUpdate?.downloadUrl }))">前往下载</NButton></div><p class="muted about-note"><ShieldCheck :size="15" />更新检查不会自动安装或替换应用。</p></section>
      <section class="surface"><div class="section-heading"><div><h2>公告</h2><p>来自当前壁纸网站</p></div><Bell :size="19" /></div><p v-if="!announcements.length" class="muted">{{ store.desktop ? '当前没有公告，可通过检查更新同步。' : '公告会在桌面应用连接网站后展示。' }}</p><article v-for="notice in announcements" :key="notice.id" class="announcement"><div><h3>{{ notice.title }}</h3><NButton v-if="store.website.dismissed[notice.id] !== notice.revision" text type="primary" @click="act('dismiss', async () => { await invoke('dismiss_website_message', { id: notice.id, revision: notice.revision }); await store.checkWebsite(); })">标为已读</NButton></div><p>{{ notice.body }}</p></article></section>
    </div></NTabPane></NTabs>
  </section>
</template>
<style scoped>
.settings-content{max-width:840px;display:grid;gap:22px;margin-top:18px}.settings-content>.surface{padding:25px}.source-field{display:grid;gap:9px;margin-bottom:8px}.source-field>label{font-weight:600;font-size:13px}.settings-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:18px}.unsaved-note{font-size:12px;color:#b88422}.source-errors{margin-top:16px}.advanced-source{margin-top:22px;border-top:1px solid var(--ui-line);padding-top:18px}.inline-field{display:flex;gap:10px}.data-location{display:flex;gap:20px;align-items:center}.data-location code{flex:1;overflow-wrap:anywhere;font-size:12px;background:#f6f8fc;border:1px solid var(--ui-line);border-radius:8px;padding:12px}.about-identity{display:flex;align-items:center;gap:22px}.about-logo{width:85px;height:85px;display:grid;place-items:center;background:#eff5ff;border-radius:20px}.about-logo img{width:64px;height:64px}.about-identity h2{font-size:22px;margin:0 0 6px}.about-identity p{color:var(--ui-muted);margin:0 0 13px}.about-identity .n-tag{margin-right:8px}.release-details{background:#f7f9fd;border-radius:10px;padding:18px}.release-details p{white-space:pre-wrap;line-height:1.8}.about-note{display:flex;gap:7px;align-items:center;font-size:12px;margin:12px 0 0}.announcement{padding:16px 0;border-top:1px solid var(--ui-line)}.announcement>div{display:flex;justify-content:space-between;align-items:center}.announcement h3{font-size:14px;margin:0}.announcement p{white-space:pre-wrap;line-height:1.8;color:var(--ui-muted);font-size:13px}@media(max-width:760px){.data-location{flex-direction:column;align-items:stretch}.inline-field{flex-direction:column}}
</style>
